const distancePresets={sprint:{swim:.75,bike:20,run:5},olympic:{swim:1.5,bike:40,run:10},half:{swim:1.9,bike:90,run:21},full:{swim:3.8,bike:180,run:42}};let currentDistances={...distancePresets.sprint},isCustomMode=!1;document.addEventListener("DOMContentLoaded",function(){initializeDistanceTabs(),initializeInputListeners(),updateDistanceDisplays()});function initializeDistanceTabs(){const s=document.querySelectorAll(".distance-tab"),t=document.getElementById("custom-distances");s.forEach(n=>{n.addEventListener("click",function(){s.forEach(c=>c.classList.remove("active")),this.classList.add("active");const i=this.dataset.distance;i==="custom"?(isCustomMode=!0,t.style.display="block",updateCustomDistances()):(isCustomMode=!1,t.style.display="none",currentDistances={...distancePresets[i]},updateDistanceDisplays()),calculateAll()})}),["custom-swim","custom-bike","custom-run","custom-swim-unit"].forEach(n=>{const i=document.getElementById(n);i&&i.addEventListener("input",updateCustomDistances)})}function updateCustomDistances(){if(!isCustomMode)return;const s=parseFloat(document.getElementById("custom-swim").value)||0,t=document.getElementById("custom-swim-unit").value,e=parseFloat(document.getElementById("custom-bike").value)||0,n=parseFloat(document.getElementById("custom-run").value)||0;currentDistances={swim:t==="m"?s/1e3:s,bike:e,run:n},updateDistanceDisplays(),calculateAll()}function updateDistanceDisplays(){const s=document.getElementById("swim-distance"),t=document.getElementById("bike-distance"),e=document.getElementById("run-distance");if(s){const n=currentDistances.swim<1?`${Math.round(currentDistances.swim*1e3)}m`:`${currentDistances.swim}km`;s.textContent=n}t&&(t.textContent=`${currentDistances.bike}km`),e&&(e.textContent=`${currentDistances.run}km`)}function initializeInputListeners(){["swim-time","bike-time","run-time","t1-time","t2-time"].forEach(e=>{const n=document.getElementById(e);n&&(n.addEventListener("input",function(){calculateFromTime(e)}),(e==="bike-time"||e==="run-time")&&n.addEventListener("blur",function(){const i=parseTimeToMinutes(n.value);i>0&&(n.value=formatTimeHMS(i),calculateFromTime(e))}))}),["swim-pace","bike-speed","run-pace"].forEach(e=>{const n=document.getElementById(e);n&&n.addEventListener("input",function(){calculateFromPace(e)})})}function calculateFromTime(s){const t=document.getElementById(s).value;if(!t)return;const e=parseTimeToMinutes(t);if(!(e<=0)){switch(s){case"swim-time":if(currentDistances.swim>0){const i=e/currentDistances.swim/10;document.getElementById("swim-pace").value=formatTime(i)}break;case"bike-time":if(currentDistances.bike>0){const n=currentDistances.bike/e*60;document.getElementById("bike-speed").value=n.toFixed(1)}break;case"run-time":if(currentDistances.run>0){const n=e/currentDistances.run;document.getElementById("run-pace").value=formatTime(n)}break}calculateTotal()}}function calculateFromPace(s){const t=document.getElementById(s).value;if(t){switch(s){case"swim-pace":const e=parseTimeToMinutes(t);if(e>0&&currentDistances.swim>0){const c=e*10*currentDistances.swim;document.getElementById("swim-time").value=formatTime(c)}break;case"bike-speed":const n=parseFloat(t);if(n>0&&currentDistances.bike>0){const c=currentDistances.bike/n*60;document.getElementById("bike-time").value=formatTimeHMS(c)}break;case"run-pace":const i=parseTimeToMinutes(t);if(i>0&&currentDistances.run>0){const c=i*currentDistances.run;document.getElementById("run-time").value=formatTimeHMS(c)}break}calculateTotal()}}function calculateAll(){["swim-time","swim-pace","bike-time","bike-speed","run-time","run-pace"].forEach(t=>{const e=document.getElementById(t);e&&e.value&&(t.includes("time")?calculateFromTime(t):calculateFromPace(t))}),calculateTotal()}function calculateTotal(){const s=parseTimeToMinutes(document.getElementById("swim-time").value)||0,t=parseTimeToMinutes(document.getElementById("bike-time").value)||0,e=parseTimeToMinutes(document.getElementById("run-time").value)||0,n=parseTimeToMinutes(document.getElementById("t1-time").value)||0,i=parseTimeToMinutes(document.getElementById("t2-time").value)||0,c=s+n+t+i+e,u=document.getElementById("total-time");u&&(u.textContent=c>0?formatTimeHMS(c):"--:--:--"),updateBreakdown(s,n,t,i,e);const o=document.querySelector(".result-display");o&&(o.classList.add("updated"),setTimeout(()=>o.classList.remove("updated"),600))}function updateBreakdown(s,t,e,n,i){Object.entries({"breakdown-swim":s,"breakdown-t1":t,"breakdown-bike":e,"breakdown-t2":n,"breakdown-run":i}).forEach(([u,o])=>{const m=document.getElementById(u);if(m){const a=u==="breakdown-bike"||u==="breakdown-run";m.textContent=o>0?a?formatTimeHMS(o):formatTime(o):a?"--:--:--":"--:--"}})}function parseTimeToMinutes(s){if(!s)return 0;const t=s.split(":");if(t.length!==2&&t.length!==3)return 0;const e=t.map(n=>/^\d+$/.test(n)?Number(n):NaN);return e.some(n=>!Number.isFinite(n))||e[e.length-1]>=60||t.length===3&&e[1]>=60?0:t.length===2?e[0]+e[1]/60:e[0]*60+e[1]+e[2]/60}function formatTime(s){if(s<=0)return"";const t=Math.round(s*60),e=Math.floor(t/60),n=t%60;return`${e}:${n.toString().padStart(2,"0")}`}function formatTimeHMS(s){if(s<=0)return"--:--:--";const t=Math.round(s*60),e=Math.floor(t/3600),n=Math.floor(t%3600/60),i=t%60;return`${e.toString().padStart(2,"0")}:${n.toString().padStart(2,"0")}:${i.toString().padStart(2,"0")}`}
